@font-face {
    font-family: "Bestin";
    src:url("data:font/woff2;base64,") format("woff2");
    font-weight: 400;
    font-display: block;
}
#accordioncat .panel-heading{border-radius:0;border:0;padding:0;}
#accordioncat .panel-heading a{display:block;padding:10px 15px;}
#accordioncat .panel-heading a:focus{text-decoration:none;}
#accordioncat .panel-heading a[aria-expanded=true]{text-decoration:none;color:#ffc400;}
#accordioncat .panel-heading .accordion-toggle:after{float:right;}
#accordioncat.panel-group .panel {
    border-radius: 0;
    border: 0;
}

#input-category {
    height: 50px;
    background: transparent;
    color: transparent;
    border: 0;
    position: absolute;
    top: 0;
    outline: none;
    box-shadow: none;
}

#accordioncat{
        position: relative;

}

/* SOURCE: catalog/view/theme/tt_uren1/stylesheet/plaza/header/header1.css */

header {background: #0c2a5c;padding-bottom: 1rem;}
header .box-inner{position:relative;display:inline-block;vertical-align:top;width:100%;text-align:center;}
header .box-inner-inner {display: grid;grid-gap: 30px;grid-template-columns: 270px 270px auto auto;align-items: center;}
header .box-inner-inner .col-logo {position: relative;}

.col-search {}
.col-cart{
}
.col-cart .inner {display:grid;grid-template-columns: auto auto;grid-gap: 3rem;}
.box-setting{}
.box-setting >button{background:#e52e06;border: 0;line-height: 5.3rem;border-radius: 3px;-webkit-border-radius: 3px;padding:0 2rem;box-shadow:none !important;-webkit-box-shadow:none !important;color: #fff;}
.box-setting >button:before{content: "\f2f7";font-size: 2.8rem;display: inline-block;vertical-align: top;line-height: inherit;}
.box-setting > .dropdown-menu{left:auto;right:-5rem;border:0;padding:20px;width:25rem;font-size: 9px;border:1px solid #ebebeb;margin-top: 1.4rem;box-shadow:none;-webkit-box-shadow:none;border-radius: 3px;-webkit-border-radius: 3px;background: #fff;}
#logo{padding: 0;position:relative;z-index:1;display:inline-block;vertical-align:top;max-width: 27rem;float: left;}
#search-by-category ::-webkit-input-placeholder{color:#a4a4a4;opacity: 1;}
#search-by-category{display:inline-block;vertical-align:top;width: 100%;}
#search-by-category .search-button{display:none;color: #222;}
.search-content{padding:0;border:0;margin:0;box-shadow:none;right:0;width:auto;position:relative;left:0;top:0;bottom:0;border-radius:0;display: block;float:none;background:transparent;z-index: auto;}
#search-by-category .search-container{position: relative;}
#search-by-category .search-container .categories-container{position:absolute;padding: 10px 0;left: 0;top: 0;background: transparent;border-top-left-radius: 3rem;border-bottom-left-radius: 3rem;}
#search-by-category .search-container #text-search{padding: 1rem 0;padding-right: 14rem;padding-left: 20rem;height: 5.3rem;border-radius: 3px;-webkit-border-radius: 3px;font-size: 1.3rem;border: 0;width:100%;z-index:1;background: #fff;color: #a4a4a4;-webkit-transition:all 0.3s ease-in-out;-moz-transition:all 0.3s ease-in-out;-ms-transition:all 0.3s ease-in-out;-o-transition:all 0.3s ease-in-out;}
#search-by-category #sp-btn-search{position:absolute;right: 0;top: 0;}
#search-by-category .search-ajax{position:absolute;z-index:9999 !important;background:none repeat scroll 0% 0% #fff;left:0px;top:100%;width:88%;min-width:25rem;}
#search-by-category .search-ajax .ajax-result-container{box-shadow:0px 0px 0.5rem rgba(0,0,0,0.1);}
#btn-search-category{border:none!important;padding: 0 1.5rem;box-shadow:none;text-shadow:none;line-height: 5.3rem;font-size: 1.6rem;letter-spacing:0;text-transform: uppercase;border-radius: 0;border-top-right-radius: 3px;border-bottom-right-radius: 3px;}

#btn-search-category span{/* display:none; */margin-left: 8px;}
@media (max-width: 767px) {
    #search-by-category .search-container #text-search {padding-right: 6rem;}
}
@media (max-width: 479px) {
    #search-by-category .search-container .categories-container {display: none;}
    #search-by-category .search-container #text-search {padding-left: 1.5rem;}
}
#wishlist-total .txt-count,#cart .txt-count{width: 2rem;height: 2rem;line-height: 2rem;font-size: 1.2rem;background: #e52e06;color:#fff;position:absolute;top: 5px;text-align:center;font-weight: 700;left: 2px;border-radius:100%;-webkit-border-radius:100%;}
#cart{display:inline-block;vertical-align:top;width: auto;}
#cart > .btn{color: #222;background: #fff;border:none;box-shadow:none;-webkit-box-shadow:none;text-shadow:none;font-weight: 400;padding: 0 2rem;text-transform:capitalize;line-height: 5.3rem;border: 0;border-radius: 3px;-webkit-border-radius: 3px;}
#cart > .btn:before{content:"\f110";font-size: 2.8rem;display:inline-block;vertical-align:top;}
#cart #cart-total {position: relative;display: inline-block;vertical-align: top;}
#cart .text-cart {display: inline-block;vertical-align: top;line-height: 1;padding: 6px 0;margin-left: 24px;text-align: left;}
#cart > .btn:after {content: "\f3d0";font-size: 2rem;display: inline-block;line-height: inherit;vertical-align: top;margin-left: 1.5rem;}
#cart .dropdown-menu{background:#fff;z-index:9999;position:fixed;right:0;top:0;margin:0;border-radius:0;-webkit-border-radius:0;box-shadow:none;-webkit-box-shadow:none;height:100%;width:90%;max-width:37.5rem;padding:3rem;font-size:1.4rem;border:0;overflow:auto;}
.pt-menu ul{list-style:none;margin:0;padding:0;}
.mobile-menu .pt-menu-bar i{height:4rem;line-height:4rem;text-align:center;font-size:3.6rem;cursor:pointer;position:absolute;left: 0;top:50%;margin-top:-2rem;z-index:3;}
.mobile-menu .pt-menu-bar i:before{display:inline-block;vertical-align:top;line-height:inherit;}
.mobile-menu .pt-menu-bar i:last-child{font-size:3rem;display:none;background:#fff;}
.mobile-menu .ul-top-items{display:none;position:fixed;left:0;top:0;height:100%;z-index:666;width:88%;max-width:37.5rem;background:#fff;padding:2rem;overflow:auto;text-align:left;}
@media (max-width: 1599px) {
    header .box-inner-inner {grid-template-columns: 270px auto;}
    header .box-inner-inner .col-logo {order: 1;}
    header .box-inner-inner .col-cart {order: 2;}
    header .box-inner-inner .col-ver {order: 3;}
    header .box-inner-inner .col-search {order: 4;}
    header .box-inner-inner .col-cart > .inner {float: right;}
}
@media (max-width:1199px){
    header .box-inner-inner {grid-template-columns: 270px auto;}
    header .box-inner-inner .col-ver {display: none;}
    header .box-inner-inner .col-search {grid-column: 1/3;}
    #logo {padding-left: 4rem;float: left;}
    .col-cart .header-phone {font-size: 2rem;}
    .col-cart .inner {grid-gap: 1.5rem;}
}
@media (max-width: 991px) {
    #logo {padding-top: 0rem;padding-bottom: 0rem;}
}
@media (max-width:767px){
    header .box-inner-inner {grid-template-columns: auto auto;grid-row-gap: 0;}
    #cart .text-cart {display: none;}
    #cart > .btn:after {display: none;}
    #wishlist-total .txt-count, #cart .txt-count {left: -5px}
    #search-by-category{width:100%;}
    #top .box-top{padding: 0;float:none !important;display:block;text-align:center;border-bottom: 1px solid rgba(255,255,255,0.1);}
    #wishlist-total,.box-setting {}
    .col-cart .header-phone:after {opacity: 0;}
}
@media (max-width:479px){
    .header-dropdown .dropdown-menu{right:-6.5rem;}
    .col-cart .inner {grid-gap: 1rem;}
    .box-setting > button,#wishlist-total,#cart > .btn,.col-cart .header-phone {width: auto;border: 0;padding: 0 1.5rem;}
    #wishlist-total .txt-count, #cart .txt-count {left: -7px;}
    .box-setting > .dropdown-menu {right: -6rem;margin-top: 9px;}
}


/* Critical responsive images */
.img-responsive { display:block; max-width:100%; height:auto; margin:auto; }

/* Critical category list overrides */
:root{--main-color:#666;--link-hover-color:#ffc400;--link-color:#222;}
.list-categories .list-group-item{border:0;color:var(--main-color)!important;line-height:3rem;padding:0;text-transform:capitalize;background:transparent!important;margin:0;}
.list-categories .list-group-item.child{position:relative;color:#888!important;padding-left:2rem;}
.list-categories .list-group-item.active,.list-categories .list-group-item.active:focus,.list-categories .list-group-item.active:hover,.list-categories .list-group-item:hover{background:none;color:var(--link-hover-color)!important;}

/* Critical mobile off-canvas columns */
@media (max-width:991px){.layer-category #column-left,.layer-category #column-right{position:fixed;left:0;top:0;width:88%;height:100%;max-width:37.5rem;z-index:555;overflow:auto;background:#fff;padding:2rem;display:none;}}
@media (max-width:991px){.layer-category #content{width:100%;}}

/* Critical product compare */
#compare-total{letter-spacing:-.05em;line-height:2.5rem;padding:1rem 0;border:0;text-transform:capitalize;background:transparent!important;color:var(--link-color);font-weight:400;font-size:1.4rem;}

/* Critical category toolbar */
.tool-bar{margin-bottom:4rem;border:0;padding:1rem 1rem 0 1rem;background:#f2f2f2;margin-top:1.5rem;}

/* Critical toolbar view buttons */
#grid-view,#list-view,.tool-bar .btn-group .btn-custom-view,.tool-bar .btn-group .btn-grid-view,.tool-bar .btn-group .btn-list-view{width:3.3rem;height:4.5rem;line-height:4.5rem;padding:0;border-radius:0!important;-webkit-border-radius:0!important;box-shadow:none!important;-webkit-box-shadow:none!important;border:0;background:transparent;text-align:center;color:#fff;text-shadow:none;font-size:0;}
.tool-bar .btn-group .btn-custom-view{margin:0!important;}
.tool-bar .btn-custom-view.btn-list,#list-view,.tool-bar .btn-group .btn-list-view{background:url(../image/bkg_list.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-list.active,.tool-bar .btn-custom-view.btn-list:hover,#list-view.active,#list-view:hover,.tool-bar .btn-group .btn-list-view.active,.tool-bar .btn-group .btn-list-view:hover{background:url(../image/bkg_list_hover.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-1{background:url(../image/bkg_grid1.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-1.active,.tool-bar .btn-custom-view.btn-grid-1:hover{background:url(../image/bkg_grid1_hover.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-2{background:url(../image/bkg_grid2.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-2.active,.tool-bar .btn-custom-view.btn-grid-2:hover{background:url(../image/bkg_grid2_hover.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-3{background:url(../image/bkg_grid.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-3.active,.tool-bar .btn-custom-view.btn-grid-3:hover{background:url(../image/bkg_grid_hover.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-4{background:url(../image/bkg_grid4.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-4.active,.tool-bar .btn-custom-view.btn-grid-4:hover{background:url(../image/bkg_grid4_hover.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-5{background:url(../image/bkg_grid5.png) center no-repeat!important;}
.tool-bar .btn-custom-view.btn-grid-5.active,.tool-bar .btn-custom-view.btn-grid-5:hover{background:url(../image/bkg_grid5_hover.png) center no-repeat!important;}

h1,h2,h3,h4,h5,h6{font-family:'Bestin';}
#content>h1,h3.text-refine{font-family:'Bestin' !important;}


body{font-family:'Work Sans',sans-serif;}
button,.btn,.btn-primary{color:#222;background-color:#ffc400;border-color:#ffc400;background-image:none;}

.breadcrumb{margin:0;padding:0;border:0;background:transparent;}.breadcrumb>li{position:relative;vertical-align:top;}.breadcrumb>li>a{text-transform:capitalize;color:#242424;}
.breadcrumb i{font-size:1.5rem;}
.breadcrumbs .container-inner{padding:1rem 0;}.breadcrumbs{text-align:center;margin-bottom:8rem;font-size:1.4rem;background:#f7f7f9;border-bottom:1px solid #f1f1f2;border-top:1px solid #f1f1f2;}.breadcrumb>li+li:before{content:"/";color:#242424;}.breadcrumb>li>a{line-height:24px;}.breadcrumb>li>a:hover,.breadcrumb>li:last-child>a{color:var(--link-hover-color);}
