#cart>.btn{max-height:53px;max-width:54.55px;}
.box-setting>button{max-width:52.75px;max-height:53px;}
.box-setting>button:before{max-height:53px;}
header .box-inner-inner .col-cart,header .box-inner-inner .col-cart>.inner{max-height:53px;}
#cart>.btn:before{max-width:24.5px;}
.box-setting>button:before{vertical-align:top;width:22.75px;height:53px;}
#btn-search-category:before{width:21px;height:53px;vertical-align:top;}
#btn-search-category{max-height:53px;}
.fa-home:before{width:13.94px;height:23px;}


.thumbnails{overflow:auto;clear:both;list-style:none;padding:0;margin:0;}
.thumbnails>li{margin-left:2rem;}
.thumbnails{margin-left:-2rem;}
.thumbnails>img{width:100%;}
.image-additional a{margin-bottom:2rem;padding:.5rem;display:block;border:1px solid #ddd;}
.image-additional{max-width:7.8rem;}
.thumbnails .image-additional{float:left;margin-left:2rem;}
#product-product .product-details>.row{position:relative;}
.product-details{position:relative;}
.product-image-details .swiper-slide{text-align:center;}
.product-image-details .cloud-zoom-gallery{position:relative;display:inline-block;vertical-align:top;border:1px solid #ededed;opacity:.7;}
.product-image-details .img-active .cloud-zoom-gallery{border-color:var(--link-hover-color);}
.product-image-details .img-active .cloud-zoom-gallery,.product-image-details .cloud-zoom-gallery:hover{opacity:1;}
.product-info-details{text-align:left;position:absolute;top:0;right:0;bottom:0;overflow:auto;}
.product-info-details .manufacture-product{margin-bottom:.2rem;}
.product-info-details .manufacture-product a{font-size:1.2rem;color:#929292;}
.product-info-details .product-tags{margin-bottom:2.3rem;clear:left;font-weight:600;font-size:1.6rem;}
.product-info-details h1{font-size:2.8rem!important;margin-top:0;margin-bottom:1.5rem;line-height:1.425;font-family:'Work Sans',sans-serif!important;}
.product-info-details .rating{margin-bottom:2.5rem;}
.product-info-details .price{font-size:2.4rem;}
.product-info-details .price .price-old{font-size:1.8rem;}
.product-info-details ul.list-unstyled{padding-top:2.3rem;margin-bottom:1.5rem;font-size:1.6rem;}
.product-info-details ul.list-unstyled li span{color:#777;}
.product-info-details ul.list-unstyled li a{color:var(--link-hover-color);}
.product-info-details #product .form-group .control-label{text-transform:capitalize;font-size:1.6rem;font-weight:600;}
.product-info-details #product .form-group .form-control{box-shadow:none;-webkit-box-shadow:none;border:1px solid #f1f1f1;color:#333;}
.product-info-details #product .form-group .control-label[for="input-quantity"]{line-height:5rem;float:left;margin:1rem .5rem 1rem 0;}
.product-info-details #product .form-group #input-quantity{width:7rem;height:5rem;text-align:center;float:left;font-size:1.6rem;color:#222;font-weight:600;margin:1rem 2rem 1rem .5rem;border:0;border-bottom:2px solid #e5e5e5;border-radius:0;-webkit-border-radius:0;background:#fff;}
.product-info-details #button-cart{float:left;margin:1rem 0;padding:0 1.5rem;line-height:5rem;text-transform:uppercase;width:auto;}
.product-info-details #product .btn-group{margin-top:0;display:block;overflow:hidden;float:left;}
.product-info-details #product .btn-group button{padding:0;line-height:4.8rem;width:5rem;border:1px solid var(--link-hover-color);text-align:center;background:transparent;color:#222;text-transform:capitalize;box-shadow:none;-webkit-box-shadow:none;margin:1rem 0 1rem 1rem;font-size:0;border-radius:3px;-webkit-border-radius:3px;}
.product-info-details #product .btn-group button:last-child{margin-right:0;}
.swiper-container{margin-left:auto;margin-right:auto;position:relative;overflow:hidden;z-index:1;direction:ltr!important;}
.swiper-wrapper{position:relative;width:100%;height:100%;z-index:1;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-transition-property:-webkit-transform;transition-property:transform;box-sizing:content-box;}
.swiper-container-android .swiper-slide,.swiper-wrapper{-webkit-transform:translate3d(0,0,0);transform:translate3d(0,0,0);}
.swiper-slide{-webkit-flex-shrink:0;-ms-flex:0 0 auto;flex-shrink:0;width:100%;height:100%;position:relative;}
.product-zoom-image{overflow:inherit;margin:0;padding:0;position:relative;z-index:5;}
.additional-container{padding:0 3rem;margin-top:2rem;}
.additional-container .additional-images{padding:0;margin:0;}
.additional-images{margin:1rem 0 0;}
.lightbox-container{display:none;}
#product-cloud-zoom{max-width:100%;height:auto!important;margin:auto;}
@media (max-width:767px){.additional-container{padding:0;}.mousetrap{max-width:100%;max-height:100%;}#cloud-zoom-big{display:none!important;}.product-info-details{position:relative;padding:0 1.5rem;margin-top:3rem;top:auto;right:auto;bottom:auto;}.swiper-button-next,.swiper-button-prev,.additional-button-prev,.additional-button-next{display:none;}}
</style>
{% endif %}

